// pragma once
// include "utils/light_list.h"
// include "utils/time.h"
namespace certain {
template <typename T>
class ArrayTimer {
 public:
  struct EltEntry {
    uint32_t index;
    struct { T* next; T* prev; } timer_list_entry;
    void Init() {
      index = 0; // For Remove method.
      do {
        (this)->timer_list_entry.next = NULL;
        (this)->timer_list_entry.prev = NULL;
      } while (0);
    }
    EltEntry() { Init(); }
  };
 private:
  const uint32_t kReadyListIndex = uint32_t(-1);
  uint32_t timer_cnt_;
  uint32_t ready_cnt_;
  uint32_t max_timeout_msec_;
  uint32_t curr_index_;
  uint64_t curr_time_msec_;
  typedef struct { T* first; T* last; } TimerList;
  TimerList* timer_list_;
  TimerList* ready_list_;
  // Return how many timer moved.
  uint32_t MoveTimerToReadyListByIndex(uint32_t index) {
    assert(index <= max_timeout_msec_);
    TimerList* curr_list = &timer_list_[index];
    uint32_t moved_cnt = 0;
    while (!((void*)(curr_list)->first == (void*)(curr_list))) {
      T* last = ((curr_list)->last);
      do {
        if ((void*)(last)->timer_entry.timer_list_entry.next == (void*)(curr_list)) (curr_list)->last = (last)->timer_entry.timer_list_entry.prev;
        else (last)->timer_entry.timer_list_entry.next->timer_entry.timer_list_entry.prev = (last)->timer_entry.timer_list_entry.prev;
        if ((void*)(last)->timer_entry.timer_list_entry.prev == (void*)(curr_list)) (curr_list)->first = (last)->timer_entry.timer_list_entry.next;
        else (last)->timer_entry.timer_list_entry.prev->timer_entry.timer_list_entry.next = (last)->timer_entry.timer_list_entry.next;
        (last)->timer_entry.timer_list_entry.next = NULL;
        (last)->timer_entry.timer_list_entry.prev = NULL;
      } while (0);
      assert(last->timer_entry.index == index);
      last->timer_entry.index = kReadyListIndex;
      do {
        (last)->timer_entry.timer_list_entry.next = (ready_list_)->first;
        *(void**)&(last)->timer_entry.timer_list_entry.prev = (void*)(ready_list_);
        if ((void*)(ready_list_)->last == (void*)(ready_list_)) (ready_list_)->last = (last);
        else (ready_list_)->first->timer_entry.timer_list_entry.prev = (last);
        (ready_list_)->first = (last);
      } while (0);
      moved_cnt++;
    }
    return moved_cnt;
  }
  // Move add all timers before curr_time_msec to ready_list_, then update
  // curr_time_msec_, curr_index_, timer_cnt_ and ready_cnt_.
  void MoveTimerToReadyList(uint64_t curr_time_msec) {
    // Fix curr_time_msec if it's not monotonnous.
    if (curr_time_msec < curr_time_msec_) {
      curr_time_msec = curr_time_msec_;
    }
    uint64_t range = curr_time_msec - curr_time_msec_;
    if (range > max_timeout_msec_) {
      range = max_timeout_msec_;
    }
    uint32_t index = curr_index_;
    uint32_t moved_cnt = 0;
    for (uint32_t i = 0; i <= range; ++i) {
      index = i + curr_index_;
      // timer_list_ array is cyclic reused.
      if (index >= max_timeout_msec_ + 1) {
        index -= max_timeout_msec_ + 1;
      }
      moved_cnt += MoveTimerToReadyListByIndex(index);
    }
    ready_cnt_ += moved_cnt;
    timer_cnt_ -= moved_cnt;
    curr_time_msec_ = curr_time_msec;
    curr_index_ = index;
  }
 public:
  // Support timer alarms in [0, max_timeout_msec].
  ArrayTimer(uint32_t max_timeout_msec) {
    timer_cnt_ = 0;
    ready_cnt_ = 0;
    max_timeout_msec_ = max_timeout_msec;
    timer_list_ = (TimerList*)calloc(max_timeout_msec_ + 1, sizeof(TimerList));
    assert(timer_list_ != NULL);
    for (uint32_t i = 0; i <= max_timeout_msec_; ++i) {
      do {
        *(void**)&(&timer_list_[i])->first = (void*)(&timer_list_[i]);
        *(void**)&(&timer_list_[i])->last = (void*)(&timer_list_[i]);
      } while (0);
    }
    ready_list_ = (TimerList*)calloc(1, sizeof(TimerList));
    do {
      *(void**)&(ready_list_)->first = (void*)(ready_list_);
      *(void**)&(ready_list_)->last = (void*)(ready_list_);
    } while (0);
    curr_index_ = 0;
    curr_time_msec_ = GetTimeByMsec();
  }
  ~ArrayTimer() {
    free(ready_list_);
    free(timer_list_);
  }
  uint32_t Size() { return timer_cnt_ + ready_cnt_; }
  bool Add(T* elt, uint32_t timeout_msec) {
    assert(timeout_msec <= max_timeout_msec_);
    if (Exist(elt)) {
      return false;
    }
    uint64_t msec = GetTimeByMsec();
    MoveTimerToReadyList(msec);
    uint32_t index = curr_index_ + timeout_msec;
    if (index >= max_timeout_msec_ + 1) {
      index -= (max_timeout_msec_ + 1);
    }
    elt->timer_entry.index = index;
    do {
      (elt)->timer_entry.timer_list_entry.next = (&timer_list_[index])->first;
      *(void**)&(elt)->timer_entry.timer_list_entry.prev = (void*)(&timer_list_[index]);
      if ((void*)(&timer_list_[index])->last == (void*)(&timer_list_[index])) (&timer_list_[index])->last = (elt);
      else (&timer_list_[index])->first->timer_entry.timer_list_entry.prev = (elt);
      (&timer_list_[index])->first = (elt);
    } while (0);
    timer_cnt_++;
    return true;
  }
  bool Remove(T* elt) {
    if (!Exist(elt)) {
      assert(elt->timer_entry.index == 0);
      return false;
    }
    TimerList* timer_list = ready_list_;
    if (elt->timer_entry.index != kReadyListIndex) {
      timer_list = &timer_list_[elt->timer_entry.index];
      timer_cnt_--;
    } else {
      ready_cnt_--;
    }
    do {
      if ((void*)(elt)->timer_entry.timer_list_entry.next == (void*)(timer_list)) (timer_list)->last = (elt)->timer_entry.timer_list_entry.prev;
      else (elt)->timer_entry.timer_list_entry.next->timer_entry.timer_list_entry.prev = (elt)->timer_entry.timer_list_entry.prev;
      if ((void*)(elt)->timer_entry.timer_list_entry.prev == (void*)(timer_list)) (timer_list)->first = (elt)->timer_entry.timer_list_entry.next;
      else (elt)->timer_entry.timer_list_entry.prev->timer_entry.timer_list_entry.next = (elt)->timer_entry.timer_list_entry.next;
      (elt)->timer_entry.timer_list_entry.next = NULL;
      (elt)->timer_entry.timer_list_entry.prev = NULL;
    } while (0);
    elt->timer_entry.Init();
    return true;
  }
  T* TakeTimerElt() {
    if (ready_cnt_ == 0) {
      MoveTimerToReadyList(GetTimeByMsec());
      if (ready_cnt_ == 0) {
        return NULL;
      }
    }
    T* elt = ((ready_list_)->last);
    bool bRemoved = Remove(elt);
    assert(bRemoved);
    return elt;
  }
  bool Exist(T* elt) {
    if (((elt)->timer_entry.timer_list_entry.next != NULL && (elt)->timer_entry.timer_list_entry.prev != NULL)) {
      return true;
    } else {
      assert(elt->timer_entry.index == 0);
      return false;
    }
  }
};
} // namespace certain


