// pragma once
// include "utils/header.h"
// include "utils/light_list.h"
namespace certain {
template <typename K, typename V>
class LruTable {
 private:
  struct LruElt;
  typedef std::unordered_map<K, LruElt> HashTable;
  typedef typename HashTable::iterator HashTableIter;
  struct LruElt {
    K key;
    V value;
    struct { LruElt* next; LruElt* prev; } list_entry;
    LruElt() {}
    LruElt(const K& _key, const V& _value) {
      key = _key;
      value = _value;
      do {
        (this)->list_entry.next = NULL;
        (this)->list_entry.prev = NULL;
      } while (0);
    }
  };
  uint64_t max_size_;
  bool auto_eliminate_;
  HashTable hash_table_;
  struct { LruElt* first; LruElt* last; } lru_list_;
 public:
  LruTable(uint64_t max_size = 1024, bool auto_eliminate = false) {
    max_size_ = max_size;
    auto_eliminate_ = auto_eliminate;
    hash_table_.reserve(max_size_);
    do {
      *(void**)&(&lru_list_)->first = (void*)(&lru_list_);
      *(void**)&(&lru_list_)->last = (void*)(&lru_list_);
    } while (0);
  }
  virtual ~LruTable() {}
  uint64_t Size() { return hash_table_.size(); }
  bool Add(const K& key, const V& value) {
    bool ok = false;
    LruElt* elt = NULL;
    HashTableIter iter = hash_table_.find(key);
    if (iter != hash_table_.end()) {
      do {
        if ((void*)(&iter->second)->list_entry.next == (void*)(&lru_list_)) (&lru_list_)->last = (&iter->second)->list_entry.prev;
        else (&iter->second)->list_entry.next->list_entry.prev = (&iter->second)->list_entry.prev;
        if ((void*)(&iter->second)->list_entry.prev == (void*)(&lru_list_)) (&lru_list_)->first = (&iter->second)->list_entry.next;
        else (&iter->second)->list_entry.prev->list_entry.next = (&iter->second)->list_entry.next;
        (&iter->second)->list_entry.next = NULL;
        (&iter->second)->list_entry.prev = NULL;
      } while (0);
      iter->second = LruElt(key, value);
      elt = &(iter->second);
    } else {
      elt = &(hash_table_[key] = LruElt(key, value));
      ok = true;
    }
    do {
      (elt)->list_entry.next = (&lru_list_)->first;
      *(void**)&(elt)->list_entry.prev = (void*)(&lru_list_);
      if ((void*)(&lru_list_)->last == (void*)(&lru_list_)) (&lru_list_)->last = (elt);
      else (&lru_list_)->first->list_entry.prev = (elt);
      (&lru_list_)->first = (elt);
    } while (0);
    if (auto_eliminate_ && hash_table_.size() > max_size_) {
      bool removed = RemoveOldest();
      assert(removed);
    }
    return ok;
  }
  bool Remove(const K& key) {
    HashTableIter iter = hash_table_.find(key);
    if (iter == hash_table_.end()) {
      return false;
    }
    do {
      if ((void*)(&iter->second)->list_entry.next == (void*)(&lru_list_)) (&lru_list_)->last = (&iter->second)->list_entry.prev;
      else (&iter->second)->list_entry.next->list_entry.prev = (&iter->second)->list_entry.prev;
      if ((void*)(&iter->second)->list_entry.prev == (void*)(&lru_list_)) (&lru_list_)->first = (&iter->second)->list_entry.next;
      else (&iter->second)->list_entry.prev->list_entry.next = (&iter->second)->list_entry.next;
      (&iter->second)->list_entry.next = NULL;
      (&iter->second)->list_entry.prev = NULL;
    } while (0);
    hash_table_.erase(iter);
    return true;
  }
  bool RemoveOldest() {
    if (hash_table_.size() == 0) {
      return false;
    }
    LruElt* elt = ((&lru_list_)->last);
    bool removed = Remove(elt->key);
    assert(removed);
    return true;
  }
  bool PeekOldest(K& key, V& value) {
    if (hash_table_.size() == 0) {
      return false;
    }
    LruElt* elt = ((&lru_list_)->last);
    key = elt->key;
    value = elt->value;
    return true;
  }
  bool Find(const K& key, V& value) {
    HashTableIter iter = hash_table_.find(key);
    if (iter == hash_table_.end()) {
      return false;
    }
    value = iter->second.value;
    return true;
  }
  bool Find(const K& key) { return hash_table_.find(key) != hash_table_.end(); }
  bool Refresh(const K& key, bool newest = true) {
    HashTableIter iter = hash_table_.find(key);
    if (iter == hash_table_.end()) {
      return false;
    }
    do {
      if ((void*)(&iter->second)->list_entry.next == (void*)(&lru_list_)) (&lru_list_)->last = (&iter->second)->list_entry.prev;
      else (&iter->second)->list_entry.next->list_entry.prev = (&iter->second)->list_entry.prev;
      if ((void*)(&iter->second)->list_entry.prev == (void*)(&lru_list_)) (&lru_list_)->first = (&iter->second)->list_entry.next;
      else (&iter->second)->list_entry.prev->list_entry.next = (&iter->second)->list_entry.next;
      (&iter->second)->list_entry.next = NULL;
      (&iter->second)->list_entry.prev = NULL;
    } while (0);
    LruElt* elt = &(iter->second);
    if (newest) {
      do {
        (elt)->list_entry.next = (&lru_list_)->first;
        *(void**)&(elt)->list_entry.prev = (void*)(&lru_list_);
        if ((void*)(&lru_list_)->last == (void*)(&lru_list_)) (&lru_list_)->last = (elt);
        else (&lru_list_)->first->list_entry.prev = (elt);
        (&lru_list_)->first = (elt);
      } while (0);
    } else {
      do {
        *(void**)&(elt)->list_entry.next = (void*)(&lru_list_);
        (elt)->list_entry.prev = (&lru_list_)->last;
        if ((void*)(&lru_list_)->first == (void*)(&lru_list_)) (&lru_list_)->first = (elt);
        else (&lru_list_)->last->list_entry.next = (elt);
        (&lru_list_)->last = (elt);
      } while (0);
    }
    return true;
  }
  bool OverLoad() { return hash_table_.size() > max_size_; }
};
} // namespace certain

